#define FONT1_ADDR 0xBFC66000u
#define FONT2_ADDR (0xBFC66000u + 0x3D68u)
#define FONT1_ROM  0x66000
#define FONT2_ROM  0x69D68
#define GLYPH_BYTES 0x1E

void krom_install(uint8_t *bios)
{
    memcpy(bios + FONT1_ROM, krom_font1, sizeof krom_font1);
    memcpy(bios + FONT2_ROM, krom_font2, sizeof krom_font2);
}

uint32_t krom2_offset(uint32_t code)
{
    uint16_t c = (uint16_t)code;
    if (c < 0x8140 || c > 0x9872) return 0;
    int idx = 1;
    while (krom_table[idx].code <= c) idx++;
    idx--;
    return (uint16_t)(c - krom_table[idx].code + krom_table[idx].offset);
}

uint32_t krom2_raw_add(uint32_t code)
{
    uint16_t c = (uint16_t)code;
    if (c >= 0x8140 && c <= 0x84BE) return FONT1_ADDR + krom2_offset(code) * GLYPH_BYTES;
    if (c >= 0x889F && c <= 0x9872) return FONT2_ADDR + krom2_offset(code) * GLYPH_BYTES;
    return 0xFFFFFFFFu;
}
